//! The privacy filter: what Kopi never stores. See `docs/PRIVACY_DESIGN.md`.
//!
//! It runs in two stages, and only the second sees content:
//!
//! 1. [`PrivacySettings::before_read`] decides from the format names and the source app. A copy
//!    that fails here is never read: it carries a concealed, transient or auto-generated marker,
//!    comes from an excluded app, arrives while capture is paused, or can only be kinds the user
//!    turned off.
//! 2. [`PrivacySettings::after_read`] decides in memory, once the classifier knows the kind and
//!    the size. Content that fails here is dropped without being stored or logged.
//!
//! [`PrivacyFilter`] shares one set of settings between the watcher thread and the app.

use std::collections::HashSet;
use std::fmt;
use std::sync::{Arc, PoisonError, RwLock};

use kopi_platform::{PasteboardTypes, uti};

use crate::storage::{ClipKind, now_ms};
use crate::watcher::{Observed, ReadFilter, Verdict};

/// Why a copy was skipped or dropped. For the "copies skipped" counter, never for a log line
/// with content.
pub mod reason {
    pub const CONCEALED: &str = "concealed";
    pub const TRANSIENT: &str = "transient";
    pub const AUTO_GENERATED: &str = "auto-generated";
    pub const EXCLUDED_APP: &str = "excluded app";
    pub const PAUSED: &str = "paused";
    pub const KIND_OFF: &str = "kind turned off";
    pub const TOO_LARGE: &str = "too large";
}

/// Format names that mark a copy as a password or another secret.
pub const CONCEALED_MARKERS: &[&str] = &[
    "org.nspasteboard.ConcealedType",
    // From before nspasteboard.org: 1Password 7 and older, and KeeWeb.
    "com.agilebits.onepassword",
    "net.antelle.keeweb",
    // Windows. Being present is the signal, whatever it holds.
    "ExcludeClipboardContentFromMonitorProcessing",
];

/// Format names that mark a copy as only passing through the clipboard.
pub const TRANSIENT_MARKERS: &[&str] = &[
    "org.nspasteboard.TransientType",
    "de.petermaurer.TransientPasteboardType",
];

/// Format names that mark a copy as made by an app rather than by the user, such as a text
/// expander's.
pub const AUTO_GENERATED_MARKERS: &[&str] = &[
    "org.nspasteboard.AutoGeneratedType",
    "com.typeit4me.clipping",
    "Pasteboard generator type",
];

/// The default for [`PrivacySettings::max_clip_bytes`]: 50 MiB.
pub const DEFAULT_MAX_CLIP_BYTES: u64 = 50 * 1024 * 1024;

/// Whether capture is paused, from the tray or the panel.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum Pause {
    #[default]
    Off,
    /// Until the user resumes.
    Indefinite,
    /// Until this time, in Unix milliseconds ("resume in 5 min / 1 h").
    Until(i64),
}

impl Pause {
    pub const fn is_paused(self, now: i64) -> bool {
        match self {
            Self::Off => false,
            Self::Indefinite => true,
            Self::Until(until) => now < until,
        }
    }
}

/// A set of [`ClipKind`]s.
#[derive(Clone, Copy, PartialEq, Eq, Hash)]
pub struct KindSet(u8);

impl KindSet {
    pub const NONE: Self = Self(0);
    pub const ALL: Self = Self((1 << ClipKind::ALL.len()) - 1);
    /// What a text format may turn out to be, depending on the text.
    const FROM_TEXT: Self = Self::NONE
        .with(ClipKind::Text)
        .with(ClipKind::RichText)
        .with(ClipKind::Link)
        .with(ClipKind::Code)
        .with(ClipKind::Color);

    const fn bit(kind: ClipKind) -> u8 {
        1 << kind as u8
    }

    pub const fn with(self, kind: ClipKind) -> Self {
        Self(self.0 | Self::bit(kind))
    }

    pub const fn without(self, kind: ClipKind) -> Self {
        Self(self.0 & !Self::bit(kind))
    }

    pub const fn contains(self, kind: ClipKind) -> bool {
        self.0 & Self::bit(kind) != 0
    }

    pub const fn union(self, other: Self) -> Self {
        Self(self.0 | other.0)
    }

    pub const fn intersects(self, other: Self) -> bool {
        self.0 & other.0 != 0
    }

    pub const fn is_empty(self) -> bool {
        self.0 == 0
    }

    pub fn iter(self) -> impl Iterator<Item = ClipKind> {
        ClipKind::ALL.into_iter().filter(move |&k| self.contains(k))
    }
}

impl FromIterator<ClipKind> for KindSet {
    fn from_iter<I: IntoIterator<Item = ClipKind>>(iter: I) -> Self {
        iter.into_iter().fold(Self::NONE, Self::with)
    }
}

impl fmt::Debug for KindSet {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_set().entries(self.iter()).finish()
    }
}

/// The kinds a copy could be classified as, judged from its format names alone. Wide on
/// purpose: a kind is ruled out only when no format on the clipboard could produce it, so the
/// classifier must never pick a kind outside this set.
pub fn possible_kinds(types: &PasteboardTypes) -> KindSet {
    types
        .items
        .iter()
        .flatten()
        .fold(KindSet::NONE, |kinds, format| kinds.union(kinds_of(format)))
}

fn kinds_of(format: &str) -> KindSet {
    match format {
        uti::PLAIN_TEXT | uti::RTF | uti::RTFD | uti::HTML => KindSet::FROM_TEXT,
        uti::URL => KindSet::NONE.with(ClipKind::Link),
        uti::PNG | uti::TIFF => KindSet::NONE.with(ClipKind::Image),
        uti::FILE_URL => KindSet::NONE.with(ClipKind::File),
        uti::COLOR => KindSet::NONE.with(ClipKind::Color),
        _ => KindSet::NONE,
    }
}

/// The user's privacy settings. The excluded apps come from the `excluded_apps` table.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PrivacySettings {
    pub paused: Pause,
    /// The kinds to capture. Settings → "don't capture images" removes [`ClipKind::Image`].
    pub kinds: KindSet,
    /// Copies larger than this, all formats together, are dropped. `limits.max_clip_bytes`.
    pub max_clip_bytes: u64,
    /// Lowercased: bundle IDs and Windows paths don't depend on case.
    excluded_apps: HashSet<String>,
}

impl Default for PrivacySettings {
    fn default() -> Self {
        Self {
            paused: Pause::Off,
            kinds: KindSet::ALL,
            max_clip_bytes: DEFAULT_MAX_CLIP_BYTES,
            excluded_apps: HashSet::new(),
        }
    }
}

impl PrivacySettings {
    /// Replaces the excluded apps, by bundle ID on macOS or exe path on Windows.
    pub fn set_excluded_apps<I, S>(&mut self, app_ids: I)
    where
        I: IntoIterator<Item = S>,
        S: AsRef<str>,
    {
        self.excluded_apps = app_ids
            .into_iter()
            .map(|id| id.as_ref().to_lowercase())
            .collect();
    }

    pub fn is_excluded(&self, app_id: &str) -> bool {
        self.excluded_apps.contains(&app_id.to_lowercase())
    }

    /// Stage one, before anything is read. Sees only format names and the source app.
    pub fn before_read(&self, observed: &Observed, now: i64) -> Verdict {
        let types = &observed.types;
        let marked = |markers: &[&str]| markers.iter().any(|m| types.contains(m));
        if marked(CONCEALED_MARKERS) {
            return Verdict::Skip(reason::CONCEALED);
        }
        if marked(TRANSIENT_MARKERS) {
            return Verdict::Skip(reason::TRANSIENT);
        }
        if marked(AUTO_GENERATED_MARKERS) {
            return Verdict::Skip(reason::AUTO_GENERATED);
        }
        // The source app is a best guess (see PLATFORM_NOTES), and may be unknown.
        let source_id = observed
            .source
            .as_ref()
            .and_then(|a| a.bundle_id.as_deref());
        if source_id.is_some_and(|id| self.is_excluded(id)) {
            return Verdict::Skip(reason::EXCLUDED_APP);
        }
        if self.paused.is_paused(now) {
            return Verdict::Skip(reason::PAUSED);
        }
        // With no format Kopi knows, the watcher skips it as unsupported.
        let possible = possible_kinds(types);
        if !possible.is_empty() && !possible.intersects(self.kinds) {
            return Verdict::Skip(reason::KIND_OFF);
        }
        Verdict::Read
    }

    /// Stage two, in memory, once the classifier knows the kind and the total size of the
    /// formats it would store. `Err` holds the reason to drop the content. Pause is checked
    /// again, in case the user paused while the copy was being read.
    pub fn after_read(
        &self,
        kind: ClipKind,
        size_bytes: u64,
        now: i64,
    ) -> Result<(), &'static str> {
        if self.paused.is_paused(now) {
            return Err(reason::PAUSED);
        }
        if size_bytes > self.max_clip_bytes {
            return Err(reason::TOO_LARGE);
        }
        if !self.kinds.contains(kind) {
            return Err(reason::KIND_OFF);
        }
        Ok(())
    }
}

/// The settings, shared between the watcher thread and the app. Clones share them, so a pause
/// from the tray reaches the watcher on its next copy.
#[derive(Debug, Clone, Default)]
pub struct PrivacyFilter(Arc<RwLock<PrivacySettings>>);

impl PrivacyFilter {
    pub fn new(settings: PrivacySettings) -> Self {
        Self(Arc::new(RwLock::new(settings)))
    }

    pub fn settings(&self) -> PrivacySettings {
        self.0
            .read()
            .unwrap_or_else(PoisonError::into_inner)
            .clone()
    }

    pub fn update(&self, f: impl FnOnce(&mut PrivacySettings)) {
        f(&mut self.0.write().unwrap_or_else(PoisonError::into_inner));
    }

    /// [`PrivacySettings::after_read`] at the current time.
    pub fn after_read(&self, kind: ClipKind, size_bytes: u64) -> Result<(), &'static str> {
        self.0
            .read()
            .unwrap_or_else(PoisonError::into_inner)
            .after_read(kind, size_bytes, now_ms())
    }
}

impl ReadFilter for PrivacyFilter {
    fn check(&self, observed: &Observed) -> Verdict {
        self.0
            .read()
            .unwrap_or_else(PoisonError::into_inner)
            .before_read(observed, now_ms())
    }

    fn max_clip_bytes(&self) -> Option<u64> {
        Some(
            self.0
                .read()
                .unwrap_or_else(PoisonError::into_inner)
                .max_clip_bytes,
        )
    }
}

#[cfg(test)]
mod tests {
    use kopi_platform::AppRef;

    use super::*;

    const NOW: i64 = 1_800_000_000_000;

    fn observed(items: &[&[&str]], source: Option<&str>) -> Observed {
        Observed {
            types: PasteboardTypes {
                change_count: 1,
                items: items
                    .iter()
                    .map(|item| item.iter().map(|&f| f.to_owned()).collect())
                    .collect(),
            },
            source: source.map(|id| AppRef {
                bundle_id: Some(id.to_owned()),
                name: None,
            }),
        }
    }

    fn text_from(source: &str) -> Observed {
        observed(&[&[uti::PLAIN_TEXT]], Some(source))
    }

    fn check(settings: &PrivacySettings, observed: &Observed) -> Verdict {
        settings.before_read(observed, NOW)
    }

    fn with_kinds(kinds: KindSet) -> PrivacySettings {
        PrivacySettings {
            kinds,
            ..PrivacySettings::default()
        }
    }

    #[test]
    fn plain_copies_are_read() {
        let settings = PrivacySettings::default();
        assert_eq!(
            check(&settings, &text_from("com.apple.Safari")),
            Verdict::Read
        );
        assert_eq!(
            check(&settings, &observed(&[&[uti::PNG]], None)),
            Verdict::Read
        );
    }

    #[test]
    fn every_marker_skips_with_its_reason() {
        let settings = PrivacySettings::default();
        let groups = [
            (CONCEALED_MARKERS, reason::CONCEALED),
            (TRANSIENT_MARKERS, reason::TRANSIENT),
            (AUTO_GENERATED_MARKERS, reason::AUTO_GENERATED),
        ];
        for (markers, why) in groups {
            for marker in markers {
                assert_eq!(
                    check(&settings, &observed(&[&[uti::PLAIN_TEXT, marker]], None)),
                    Verdict::Skip(why),
                    "{marker}"
                );
            }
        }
    }

    #[test]
    fn a_marker_on_any_item_counts() {
        let copy = observed(
            &[
                &[uti::FILE_URL],
                &[uti::FILE_URL, "org.nspasteboard.ConcealedType"],
            ],
            None,
        );
        assert_eq!(
            check(&PrivacySettings::default(), &copy),
            Verdict::Skip(reason::CONCEALED)
        );
    }

    #[test]
    fn markers_skip_even_when_the_app_is_excluded_or_capture_is_paused() {
        let mut settings = PrivacySettings {
            paused: Pause::Indefinite,
            ..PrivacySettings::default()
        };
        settings.set_excluded_apps(["com.1password.1password"]);
        let copy = observed(
            &[&[uti::PLAIN_TEXT, "org.nspasteboard.ConcealedType"]],
            Some("com.1password.1password"),
        );
        assert_eq!(check(&settings, &copy), Verdict::Skip(reason::CONCEALED));
    }

    #[test]
    fn excluded_apps_are_skipped_whatever_the_case() {
        let mut settings = PrivacySettings::default();
        settings.set_excluded_apps(["com.apple.Passwords", "org.keepassxc.keepassxc"]);
        for id in [
            "com.apple.Passwords",
            "com.apple.passwords",
            "ORG.KEEPASSXC.KEEPASSXC",
        ] {
            assert_eq!(
                check(&settings, &text_from(id)),
                Verdict::Skip(reason::EXCLUDED_APP),
                "{id}"
            );
        }
        assert_eq!(
            check(&settings, &text_from("com.apple.Notes")),
            Verdict::Read
        );
    }

    #[test]
    fn an_unknown_source_app_is_not_excluded() {
        let mut settings = PrivacySettings::default();
        settings.set_excluded_apps(["com.apple.Passwords"]);
        assert_eq!(
            check(&settings, &observed(&[&[uti::PLAIN_TEXT]], None)),
            Verdict::Read
        );
        let nameless = Observed {
            source: Some(AppRef {
                bundle_id: None,
                name: Some("Passwords".into()),
            }),
            ..text_from("unused")
        };
        assert_eq!(check(&settings, &nameless), Verdict::Read);
    }

    #[test]
    fn excluded_apps_can_be_replaced() {
        let mut settings = PrivacySettings::default();
        settings.set_excluded_apps(["com.apple.Passwords"]);
        settings.set_excluded_apps(["com.bitwarden.desktop"]);
        assert!(!settings.is_excluded("com.apple.Passwords"));
        assert!(settings.is_excluded("com.bitwarden.desktop"));
    }

    #[test]
    fn paused_skips_until_it_ends() {
        let copy = text_from("com.apple.Notes");
        let paused = |paused| PrivacySettings {
            paused,
            ..PrivacySettings::default()
        };
        assert_eq!(
            check(&paused(Pause::Indefinite), &copy),
            Verdict::Skip(reason::PAUSED)
        );
        assert_eq!(
            check(&paused(Pause::Until(NOW + 1)), &copy),
            Verdict::Skip(reason::PAUSED)
        );
        assert_eq!(check(&paused(Pause::Until(NOW)), &copy), Verdict::Read);
        assert_eq!(check(&paused(Pause::Off), &copy), Verdict::Read);
    }

    #[test]
    fn a_kind_known_from_the_formats_is_skipped_when_off() {
        let no_images = with_kinds(KindSet::ALL.without(ClipKind::Image));
        assert_eq!(
            check(&no_images, &observed(&[&[uti::PNG, uti::TIFF]], None)),
            Verdict::Skip(reason::KIND_OFF)
        );
        let no_files = with_kinds(KindSet::ALL.without(ClipKind::File));
        assert_eq!(
            check(
                &no_files,
                &observed(&[&[uti::FILE_URL], &[uti::FILE_URL]], None)
            ),
            Verdict::Skip(reason::KIND_OFF)
        );
        let no_colors = with_kinds(KindSet::ALL.without(ClipKind::Color));
        assert_eq!(
            check(&no_colors, &observed(&[&[uti::COLOR]], None)),
            Verdict::Skip(reason::KIND_OFF)
        );
    }

    #[test]
    fn a_copy_that_might_be_a_kind_still_on_is_read() {
        // An image with a caption could be text, so it's read and decided after.
        let no_images = with_kinds(KindSet::ALL.without(ClipKind::Image));
        assert_eq!(
            check(&no_images, &observed(&[&[uti::PNG, uti::HTML]], None)),
            Verdict::Read
        );
        // Plain text might be a link.
        let links_only = with_kinds(KindSet::NONE.with(ClipKind::Link));
        assert_eq!(
            check(&links_only, &text_from("com.apple.Notes")),
            Verdict::Read
        );
    }

    #[test]
    fn text_is_skipped_when_every_kind_it_could_be_is_off() {
        let images_only = with_kinds(KindSet::NONE.with(ClipKind::Image));
        assert_eq!(
            check(&images_only, &text_from("com.apple.Notes")),
            Verdict::Skip(reason::KIND_OFF)
        );
    }

    #[test]
    fn unknown_formats_are_left_to_the_watcher() {
        let nothing = with_kinds(KindSet::NONE);
        assert_eq!(
            check(&nothing, &observed(&[&["com.example.private"]], None)),
            Verdict::Read
        );
    }

    #[test]
    fn every_captured_format_maps_to_a_kind() {
        for format in uti::CAPTURE {
            assert!(!kinds_of(format).is_empty(), "{format}");
        }
    }

    #[test]
    fn after_read_drops_content_over_the_limit() {
        let settings = PrivacySettings {
            max_clip_bytes: 100,
            ..PrivacySettings::default()
        };
        assert_eq!(settings.after_read(ClipKind::Text, 100, NOW), Ok(()));
        assert_eq!(
            settings.after_read(ClipKind::Text, 101, NOW),
            Err(reason::TOO_LARGE)
        );
    }

    #[test]
    fn after_read_drops_kinds_known_only_from_the_content() {
        let settings = with_kinds(KindSet::ALL.without(ClipKind::Link).without(ClipKind::Code));
        for kind in [ClipKind::Link, ClipKind::Code] {
            assert_eq!(settings.after_read(kind, 10, NOW), Err(reason::KIND_OFF));
        }
        assert_eq!(settings.after_read(ClipKind::Text, 10, NOW), Ok(()));
        let no_colors = with_kinds(KindSet::ALL.without(ClipKind::Color));
        assert_eq!(
            no_colors.after_read(ClipKind::Color, 10, NOW),
            Err(reason::KIND_OFF)
        );
    }

    #[test]
    fn after_read_drops_a_copy_paused_during_the_read() {
        let settings = PrivacySettings {
            paused: Pause::Until(NOW + 1),
            ..PrivacySettings::default()
        };
        assert_eq!(
            settings.after_read(ClipKind::Text, 10, NOW),
            Err(reason::PAUSED)
        );
    }

    #[test]
    fn kind_sets() {
        assert_eq!(KindSet::ALL.iter().count(), ClipKind::ALL.len());
        assert!(KindSet::NONE.is_empty());
        let set: KindSet = [ClipKind::Link, ClipKind::Code].into_iter().collect();
        assert!(set.contains(ClipKind::Link) && !set.contains(ClipKind::Text));
        assert_eq!(format!("{set:?}"), "{Link, Code}");
    }

    #[test]
    fn the_filter_shares_its_settings_with_its_clones() {
        let filter = PrivacyFilter::default();
        let watcher_side: Box<dyn ReadFilter> = Box::new(filter.clone());
        let copy = text_from("com.bitwarden.desktop");
        assert_eq!(watcher_side.check(&copy), Verdict::Read);

        filter.update(|s| s.set_excluded_apps(["com.bitwarden.desktop"]));
        assert_eq!(
            watcher_side.check(&copy),
            Verdict::Skip(reason::EXCLUDED_APP)
        );

        filter.update(|s| s.max_clip_bytes = 1024);
        assert_eq!(watcher_side.max_clip_bytes(), Some(1024));
        assert_eq!(
            filter.after_read(ClipKind::Text, 2048),
            Err(reason::TOO_LARGE)
        );
    }
}
